	s := openTestPostgres(t)

	_, err := s.CreateTask(ctx, store.NewTask{ProjectID: 1 << 40, Title: "orphan", Priority: "low"})
	if !errors.Is(err, store.ErrForeignKey) {
		t.Fatalf("CreateTask err = %v, want ErrForeignKey", err)
	}
}

